CREATE TABLE auth_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_session (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE INDEX auth_session_user ON auth_session(user_id);
CREATE TABLE auth_account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,account_id));
CREATE TABLE auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX auth_verification_identifier ON auth_verification(identifier);
CREATE TABLE profiles (id text PRIMARY KEY REFERENCES auth_user(id) ON DELETE CASCADE, github_id text NOT NULL UNIQUE, login text NOT NULL, name text NOT NULL, avatar text, bio text, tools text[] NOT NULL DEFAULT '{}', x_handle text NOT NULL DEFAULT '', published_at timestamptz, hidden_at timestamptz, last_sync_at timestamptz, last_full_at timestamptz, next_sync_at timestamptz, last_requested_at timestamptz, last_seen_at timestamptz NOT NULL DEFAULT now(), sync_state text NOT NULL DEFAULT 'pending', sync_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX profiles_login ON profiles(lower(login));
CREATE INDEX profiles_due ON profiles(next_sync_at) WHERE published_at IS NOT NULL AND hidden_at IS NULL;
CREATE TABLE daily_stats (profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, day date NOT NULL, commits integer NOT NULL CHECK(commits>=0), prs integer NOT NULL CHECK(prs>=0), issues integer NOT NULL CHECK(issues>=0), reviews integer NOT NULL CHECK(reviews>=0), PRIMARY KEY(profile_id,day));
CREATE TABLE ranking_snapshots (id uuid PRIMARY KEY, period integer NOT NULL CHECK(period IN (7,30)), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ranking_entries (snapshot_id uuid NOT NULL REFERENCES ranking_snapshots(id) ON DELETE CASCADE, profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, position integer NOT NULL, score integer NOT NULL, commits integer NOT NULL, prs integer NOT NULL, issues integer NOT NULL, reviews integer NOT NULL, active_days integer NOT NULL, PRIMARY KEY(snapshot_id,profile_id));
CREATE INDEX ranking_page ON ranking_entries(snapshot_id,position,profile_id);
CREATE TABLE rank_history (day date NOT NULL, period integer NOT NULL, profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, position integer NOT NULL, score integer NOT NULL, PRIMARY KEY(day,period,profile_id));
CREATE TABLE sync_runs (id uuid PRIMARY KEY, profile_id text NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, state text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, error_code text);
CREATE TABLE worker_health (id text PRIMARY KEY, instance_id uuid NOT NULL, revision text NOT NULL, heartbeat_at timestamptz NOT NULL, oldest_runnable_at timestamptz, progress_at timestamptz);
CREATE TABLE agent_registrations (id uuid PRIMARY KEY, name text NOT NULL, platform text NOT NULL, token_hash text NOT NULL UNIQUE, state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','completed','rejected','expired')), owner_id text REFERENCES auth_user(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, polled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_credentials (id uuid PRIMARY KEY, owner_id text NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, name text NOT NULL, platform text NOT NULL, token_hash text NOT NULL UNIQUE, scopes text[] NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, last_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX agent_owner ON agent_credentials(owner_id);
CREATE TABLE advertisers (id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaigns (id uuid PRIMARY KEY, advertiser_id uuid NOT NULL REFERENCES advertisers(id), title text NOT NULL, description text NOT NULL, url text NOT NULL, image text, placements text[] NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('draft','active','paused','ended')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at));
CREATE INDEX campaigns_active ON campaigns(starts_at,ends_at) WHERE status='active';
CREATE TABLE advertiser_leads (id uuid PRIMARY KEY, name text NOT NULL, email text NOT NULL, url text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','conversation','closed')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad_events (exposure_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('impression','click')), campaign_id uuid NOT NULL REFERENCES campaigns(id), placement text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(exposure_id,kind));
CREATE TABLE ad_daily (campaign_id uuid NOT NULL REFERENCES campaigns(id), placement text NOT NULL, day date NOT NULL, impressions integer NOT NULL DEFAULT 0, clicks integer NOT NULL DEFAULT 0, PRIMARY KEY(campaign_id,placement,day));
CREATE TABLE rate_limits (key text PRIMARY KEY, hits integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE audit_log (id uuid PRIMARY KEY, actor_id text, action text NOT NULL, target_id text NOT NULL, detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
